type CardIDBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *CardIDBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(CardID{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	CardIDReset((*CardID)(p))
	return true
}
func (b *CardIDBuilder) GetRoot() *CardID {
	if b.Arena.Locked {
		return nil
	}
	return (*CardID)(b.Arena.At(b.root))
}
func (b *CardIDBuilder) AsConst() *CardID {
	if len(b.region) == 0 {
		return nil
	}
	return (*CardID)(unsafe.Pointer(&b.region[0]))
}
func (b *CardIDBuilder) Region() []byte { return b.region }
func (b *CardIDBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), CardIDTableType(), &b.Arena)
}
func (b *CardIDBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), CardIDTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *CardIDBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), CardIDTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *CardIDBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

