type ReaderSpendBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ReaderSpendBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ReaderSpend{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ReaderSpendReset((*ReaderSpend)(p))
	return true
}
func (b *ReaderSpendBuilder) GetRoot() *ReaderSpend {
	if b.Arena.Locked {
		return nil
	}
	return (*ReaderSpend)(b.Arena.At(b.root))
}
func (b *ReaderSpendBuilder) AsConst() *ReaderSpend {
	if len(b.region) == 0 {
		return nil
	}
	return (*ReaderSpend)(unsafe.Pointer(&b.region[0]))
}
func (b *ReaderSpendBuilder) Region() []byte { return b.region }
