// DayGapReset restores DayGap's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func DayGapReset(value *DayGap) {
	value.Provider = 0.0
	value.ProviderInternal = 0.0
}

func DayGapMeasureBody(value *DayGap, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Provider != 0.0 {
		bytes += tableLebBytes(ids.refAtHit(349, 0xd02b4c8c65fb54dc)) + 1 + 8
	} // provider
	if value.ProviderInternal != 0.0 {
		bytes += tableLebBytes(ids.refAtHit(248, 0x8f19a26151ce74bc)) + 1 + 8
	} // provider_internal
	if ids.Overflow {
		return -1
	}
	return bytes
}

func DayGapMeasure(value *DayGap) int64 {
	var ids TableIds
	body := DayGapMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func DayGapMeasureReason(value *DayGap) (int64, error) {
	size := DayGapMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
