type CostCheckBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *CostCheckBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(CostCheck{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	CostCheckReset((*CostCheck)(p))
	return true
}
func (b *CostCheckBuilder) GetRoot() *CostCheck {
	if b.Arena.Locked {
		return nil
	}
	return (*CostCheck)(b.Arena.At(b.root))
}
func (b *CostCheckBuilder) AsConst() *CostCheck {
	if len(b.region) == 0 {
		return nil
	}
	return (*CostCheck)(unsafe.Pointer(&b.region[0]))
}
func (b *CostCheckBuilder) Region() []byte { return b.region }
func (b *CostCheckBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), CostCheckTableType(), &b.Arena)
}
func (b *CostCheckBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), CostCheckTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *CostCheckBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), CostCheckTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *CostCheckBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
