func LandingLoadBuilder(b *LandingBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, LandingTableType(), LandingTableType().NodeType, 2, report)
}

type LandingBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *LandingBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Landing{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	LandingReset((*Landing)(p))
	return true
}
func (b *LandingBuilder) GetRoot() *Landing {
	if b.Arena.Locked {
		return nil
	}
	return (*Landing)(b.Arena.At(b.root))
}
func (b *LandingBuilder) AsConst() *Landing {
	if len(b.region) == 0 {
		return nil
	}
	return (*Landing)(unsafe.Pointer(&b.region[0]))
}
func (b *LandingBuilder) Region() []byte { return b.region }
func (b *LandingBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), LandingTableType(), &b.Arena)
}
func (b *LandingBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), LandingTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *LandingBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), LandingTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *LandingBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

