type PriorityCardsBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *PriorityCardsBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(PriorityCards{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	PriorityCardsReset((*PriorityCards)(p))
	return true
}
func (b *PriorityCardsBuilder) GetRoot() *PriorityCards {
	if b.Arena.Locked {
		return nil
	}
	return (*PriorityCards)(b.Arena.At(b.root))
}
func (b *PriorityCardsBuilder) AsConst() *PriorityCards {
	if len(b.region) == 0 {
		return nil
	}
	return (*PriorityCards)(unsafe.Pointer(&b.region[0]))
}
func (b *PriorityCardsBuilder) Region() []byte { return b.region }
func (b *PriorityCardsBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), PriorityCardsTableType(), &b.Arena)
}
func (b *PriorityCardsBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), PriorityCardsTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *PriorityCardsBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), PriorityCardsTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *PriorityCardsBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
