type NoteBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *NoteBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Note{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	NoteReset((*Note)(p))
	return true
}
func (b *NoteBuilder) GetRoot() *Note {
	if b.Arena.Locked {
		return nil
	}
	return (*Note)(b.Arena.At(b.root))
}
func (b *NoteBuilder) AsConst() *Note {
	if len(b.region) == 0 {
		return nil
	}
	return (*Note)(unsafe.Pointer(&b.region[0]))
}
func (b *NoteBuilder) Region() []byte { return b.region }
func (b *NoteBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), NoteTableType(), &b.Arena)
}
func (b *NoteBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), NoteTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *NoteBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), NoteTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *NoteBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
