// SentinelPairReset restores SentinelPair's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func SentinelPairReset(value *SentinelPair) {
	value.Key = 0
	SentinelCountsReset(&value.Counts)
}

func SentinelPairMeasureBody(value *SentinelPair, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !SentinelPairSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func SentinelPairSaveBody(w *TableWriter, value *SentinelPair) bool {
	if !SentinelPairSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func SentinelPairSaveBodyFields(w *TableWriter, value *SentinelPair) bool {
	{
		if value.Key != 0 {
			if ref := w.Ids.refAtHit(99, 0x3dc94a19365b10ec); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Key == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Key)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		mark := w.Ids.Count
		ref := w.Ids.refAtHit(324, 0xc341febe5aae51e5)
		start := w.Ids.Count
		n := SentinelCountsMeasureBody(&value.Counts, w.Ids)
		if n < 0 || w.Ids.Overflow {
			return false
		}
		if n > 1 {
			if w.Measuring {
				w.Advance(tableLebBytes(ref) + 1 + tableLebBytes(uint64(n)) + n)
			} else {
				w.Ids.Truncate(start)
				if !w.headerPair(ref, 13) {
					w.headerRest(ref, 13)
				}
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if !SentinelCountsSaveBody(w, &value.Counts) {
					return false
				}
			}
		} else {
			w.Ids.Truncate(mark)
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func SentinelPairLoadBody(r *TableReader, value *SentinelPair) bool {
	SentinelPairReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x3dc94a19365b10ec: // key
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Key, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xc341febe5aae51e5: // counts
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			SentinelCountsLoadBody(&sub, &value.Counts)
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				SentinelCountsReset(&value.Counts)
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

