// RttSampleReset restores RttSample's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RttSampleReset(value *RttSample) {
	value.Start = 0
	value.Us = 0
}

func RttSampleMeasureBody(value *RttSample, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Start != 0 {
		bytes += tableLebBytes(ids.refAtHit(404, 0xee5d97ad45ad251f)) + 1 + 8
	} // start
	if value.Us != 0 {
		bytes += tableLebBytes(ids.refAtHit(17, 0x08c43d07b566de99)) + 1 + 8
	} // us
	if ids.Overflow {
		return -1
	}
	return bytes
}

func RttSampleMeasure(value *RttSample) int64 {
	var ids TableIds
	body := RttSampleMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func RttSampleMeasureReason(value *RttSample) (int64, error) {
	size := RttSampleMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func RttSampleSaveBody(w *TableWriter, value *RttSample) bool {
	if !RttSampleSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func RttSampleSaveBodyFields(w *TableWriter, value *RttSample) bool {
	{
		if value.Start != 0 {
			if ref := w.Ids.refAtHit(404, 0xee5d97ad45ad251f); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.Start))
		}
	}
	{
		if value.Us != 0 {
			if ref := w.Ids.refAtHit(17, 0x08c43d07b566de99); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.Us))
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func RttSampleSave(value *RttSample, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !RttSampleSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func RttSampleLoadBody(r *TableReader, value *RttSample) bool {
	RttSampleReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0xee5d97ad45ad251f: // start
			if kind != 5 {
				if tableKindWidens(kind, 5) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.Start = int64(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int64(r.Get64())
				value.Start = int64(v)
			}
		case 0x08c43d07b566de99: // us
			if kind != 5 {
				if tableKindWidens(kind, 5) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.Us = int64(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int64(r.Get64())
				value.Us = int64(v)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

func RttSampleLoad(value *RttSample, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		RttSampleReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !RttSampleLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			RttSampleReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		RttSampleReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

