type StopBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *StopBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Stop{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	StopReset((*Stop)(p))
	return true
}
func (b *StopBuilder) GetRoot() *Stop {
	if b.Arena.Locked {
		return nil
	}
	return (*Stop)(b.Arena.At(b.root))
}
func (b *StopBuilder) AsConst() *Stop {
	if len(b.region) == 0 {
		return nil
	}
	return (*Stop)(unsafe.Pointer(&b.region[0]))
}
func (b *StopBuilder) Region() []byte { return b.region }
func (b *StopBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), StopTableType(), &b.Arena)
}
func (b *StopBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), StopTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *StopBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), StopTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *StopBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

