func LoadSampleLoadMessages(values []LoadSample, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !LoadSampleLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// MeterTicksReset restores MeterTicks's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MeterTicksReset(value *MeterTicks) {
	value.Busy = 0
	value.Total = 0
}

func MeterTicksMeasureBody(value *MeterTicks, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Busy != 0 {
		bytes += tableLebBytes(ids.refAtHit(444, 0xff75d19be2aea620)) + 1 + 8
	} // busy
	if value.Total != 0 {
		bytes += tableLebBytes(ids.refAtHit(77, 0x2dcede7d543a4ffd)) + 1 + 8
	} // total
	if ids.Overflow {
		return -1
	}
	return bytes
}

func MeterTicksMeasure(value *MeterTicks) int64 {
	var ids TableIds
	body := MeterTicksMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func MeterTicksMeasureReason(value *MeterTicks) (int64, error) {
	size := MeterTicksMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
