type MeterStateBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *MeterStateBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(MeterState{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	MeterStateReset((*MeterState)(p))
	return true
}
func (b *MeterStateBuilder) GetRoot() *MeterState {
	if b.Arena.Locked {
		return nil
	}
	return (*MeterState)(b.Arena.At(b.root))
}
func (b *MeterStateBuilder) AsConst() *MeterState {
	if len(b.region) == 0 {
		return nil
	}
	return (*MeterState)(unsafe.Pointer(&b.region[0]))
}
func (b *MeterStateBuilder) Region() []byte { return b.region }
func (b *MeterStateBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), MeterStateTableType(), &b.Arena)
}
func (b *MeterStateBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), MeterStateTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *MeterStateBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), MeterStateTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *MeterStateBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

