func FriendReportEmplace(worker *TableWorker, slot *TableRef) *FriendReport {
	p, ref := worker.Alloc(int64(unsafe.Sizeof(FriendReport{})))
	*slot = ref
	if p == nil {
		return nil
	}
	value := (*FriendReport)(p)
	FriendReportReset(value)
	return value
}
