// LiveSeenPairReset restores LiveSeenPair's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LiveSeenPairReset(value *LiveSeenPair) {
	value.Key = 0
	value.At = 0
}

func LiveSeenPairMeasureBody(value *LiveSeenPair, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !LiveSeenPairSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func LiveSeenPairSaveBody(w *TableWriter, value *LiveSeenPair) bool {
	if !LiveSeenPairSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func LiveSeenPairSaveBodyFields(w *TableWriter, value *LiveSeenPair) bool {
	{
		if value.Key != 0 {
			if ref := w.Ids.refAtHit(99, 0x3dc94a19365b10ec); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Key == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Key)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.At != 0 {
			if ref := w.Ids.refAtHit(12, 0x089c4e07b545a968); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.At))
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

