type CheckRecordBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *CheckRecordBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(CheckRecord{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	CheckRecordReset((*CheckRecord)(p))
	return true
}
func (b *CheckRecordBuilder) GetRoot() *CheckRecord {
	if b.Arena.Locked {
		return nil
	}
	return (*CheckRecord)(b.Arena.At(b.root))
}
func (b *CheckRecordBuilder) AsConst() *CheckRecord {
	if len(b.region) == 0 {
		return nil
	}
	return (*CheckRecord)(unsafe.Pointer(&b.region[0]))
}
func (b *CheckRecordBuilder) Region() []byte { return b.region }
func (b *CheckRecordBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), CheckRecordTableType(), &b.Arena)
}
func (b *CheckRecordBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), CheckRecordTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *CheckRecordBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), CheckRecordTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *CheckRecordBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
