func ResetStreamLoadBody(r *TableReader, value *ResetStream) bool {
	ResetStreamReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x0bef0691197c9f78: // cost
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Cost, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xdd3bf9933387198d: // landed
			if kind != 5 {
				if tableKindWidens(kind, 5) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.Landed = int64(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int64(r.Get64())
				value.Landed = int64(v)
			}
		case 0x42e380b861ee97d7: // total_cost
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.TotalCost, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x95676bba1360fcfe: // total_usd
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.TotalUsd, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xed90c66b452f42d0: // work_cost
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.WorkCost, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x04d23c7555fd602f: // read_cost
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.ReadCost, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xf5b4630751f7ecab: // decide_cost
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.DecideCost, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x23b885a1b02092b5: // cost_by_tier
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
					break
				}
				if elemKind != 13 {
					if !tableKindWidens(elemKind, 13) {
						r.Report.KindMismatch++
						break
					}
					r.Report.Widened++
				}
				slot := (*tableContainer)(unsafe.Pointer(&value.CostByTier))
				if !tableContainerFill(&sub.Nodes.Carve, slot, count, int64(unsafe.Sizeof(*new(TextPairRow))), 8) {
					if sub.Nodes.Carve.Refused {
						r.Take(sub)
						return false
					}
					r.Report.Malformed = true
					break
				}
				slot.Count = 0
				for i := uint64(0); i < count; i++ {
					p := (*TextPairRow)(tableContainerFillAt(&sub.Nodes.Carve, slot, int32(i), int64(unsafe.Sizeof(*new(TextPairRow)))))
					if p == nil {
						r.Report.Malformed = true
						break
					}
					landed := false
					for once := true; once; once = false {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						TextPairLoadBody(&elem, p)
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							TextPairReset(p)
						}
						landed = true
					}
					if !landed {
						if sub.Nodes.Carve.Worker != nil {
							tableContainerErase(sub.Nodes.Carve.Worker.Arena, slot, unsafe.Pointer(p), int64(unsafe.Sizeof(*p)))
						}
						break
					}
					if sub.Nodes.Carve.Worker == nil {
						slot.Count++
					}
				}
				r.Take(sub)
				if r.Nodes.Carve.Refused {
					return false
				}
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

