// ResetResultReset restores ResetResult's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ResetResultReset(value *ResetResult) {
	ResetMarkReset(&value.Mark)
	value.Replaced = 0
	value.DryRun = false
	value.Replay = false
	value.Said = TableList[LineRow]{}
	value.Refused = 0
}

func ResetResultMeasureBody(value *ResetResult, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ResetResultSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ResetResultSaveBody(w *TableWriter, value *ResetResult) bool {
	if !ResetResultSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
