type TidyInFlightBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *TidyInFlightBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(TidyInFlight{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	TidyInFlightReset((*TidyInFlight)(p))
	return true
}
func (b *TidyInFlightBuilder) GetRoot() *TidyInFlight {
	if b.Arena.Locked {
		return nil
	}
	return (*TidyInFlight)(b.Arena.At(b.root))
}
func (b *TidyInFlightBuilder) AsConst() *TidyInFlight {
	if len(b.region) == 0 {
		return nil
	}
	return (*TidyInFlight)(unsafe.Pointer(&b.region[0]))
}
func (b *TidyInFlightBuilder) Region() []byte { return b.region }
func (b *TidyInFlightBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), TidyInFlightTableType(), &b.Arena)
}
func (b *TidyInFlightBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), TidyInFlightTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *TidyInFlightBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), TidyInFlightTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *TidyInFlightBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// StatsRecordReset restores StatsRecord's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StatsRecordReset(value *StatsRecord) {
	value.Epoch = 0
	value.Since = 0
	value.Reason = 0
	value.By = 0
	value.Kinds = TableList[KindTimeRow]{}
	value.Streams = TableList[StreamBasePairRow]{}
	value.Archives = TableList[LineRow]{}
	value.ResetMark = 0
	value.Tidying = 0
}

