func RoutePricesLoadBuilder(b *RoutePricesBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, RoutePricesTableType(), RoutePricesTableType().NodeType, 2, report)
}

type RoutePricesBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *RoutePricesBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(RoutePrices{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	RoutePricesReset((*RoutePrices)(p))
	return true
}
func (b *RoutePricesBuilder) GetRoot() *RoutePrices {
	if b.Arena.Locked {
		return nil
	}
	return (*RoutePrices)(b.Arena.At(b.root))
}
func (b *RoutePricesBuilder) AsConst() *RoutePrices {
	if len(b.region) == 0 {
		return nil
	}
	return (*RoutePrices)(unsafe.Pointer(&b.region[0]))
}
func (b *RoutePricesBuilder) Region() []byte { return b.region }
func (b *RoutePricesBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), RoutePricesTableType(), &b.Arena)
}
func (b *RoutePricesBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), RoutePricesTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *RoutePricesBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), RoutePricesTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *RoutePricesBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// RouteReset restores Route's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RouteReset(value *Route) {
	value.Name = 0
	value.Tier = 0
	value.Provider = 0
	value.Model = 0
	value.Harness = 0
	value.Tokens = 0
	value.Usd = 0
	value.Deadline = 0
	value.Enabled = false
	value.First = false
	RoutePricesReset(&value.Prices)
}

