// TidyResultReset restores TidyResult's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TidyResultReset(value *TidyResult) {
	value.Archive = 0
	value.DryRun = false
	value.Refused = 0
	value.Said = TableList[LineRow]{}
	StatsArchiveReset(&value.Record)
	value.Moved = 0
	value.Kept = 0
}

