type TidyResultBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *TidyResultBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(TidyResult{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	TidyResultReset((*TidyResult)(p))
	return true
}
func (b *TidyResultBuilder) GetRoot() *TidyResult {
	if b.Arena.Locked {
		return nil
	}
	return (*TidyResult)(b.Arena.At(b.root))
}
