func (b *TidyResultBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), TidyResultTableType(), &b.Arena)
}
func (b *TidyResultBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), TidyResultTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *TidyResultBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), TidyResultTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *TidyResultBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
func TidyResultSaidAdd(worker *TableWorker, holder *TableList[LineRow]) *LineRow {
	p := (*LineRow)(tableContainerAppend(worker, (*tableContainer)(unsafe.Pointer(holder)), int64(unsafe.Sizeof(*new(LineRow)))))
	if p == nil {
		return nil
	}
	LineReset(p)
	return p
}
func TidyResultSaidErase(arena *TableArena, holder *TableList[LineRow], element *LineRow) bool {
	return tableContainerErase(arena, (*tableContainer)(unsafe.Pointer(holder)), unsafe.Pointer(element), int64(unsafe.Sizeof(*element)))
}
func TidyResultSaidEach(holder *TableList[LineRow], visit func(*LineRow) bool, arena ...*TableArena) bool {
	cursor := tableContainerCursorBegin((*tableContainer)(unsafe.Pointer(holder)), int64(unsafe.Sizeof(*new(LineRow))), tableOptionalArena(arena))
	for i := int32(0); i < holder.Count; i++ {
		p := (*LineRow)(cursor.Next())
		if p == nil || !visit(p) {
			return false
		}
	}
	return true
}

// StuckReset restores Stuck's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StuckReset(value *Stuck) {
	value.Op = 0
	value.Verb = 0
	value.At = 0
	value.Seen = 0
	value.Why = 0
	value.Repaired = 0
	value.RepairedAt = 0
}

func StuckMeasureBody(value *Stuck, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !StuckSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func StuckSaveBody(w *TableWriter, value *Stuck) bool {
	if !StuckSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
