type StuckBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *StuckBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Stuck{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	StuckReset((*Stuck)(p))
	return true
}
func (b *StuckBuilder) GetRoot() *Stuck {
	if b.Arena.Locked {
		return nil
	}
	return (*Stuck)(b.Arena.At(b.root))
}
func (b *StuckBuilder) AsConst() *Stuck {
	if len(b.region) == 0 {
		return nil
	}
	return (*Stuck)(unsafe.Pointer(&b.region[0]))
}
func (b *StuckBuilder) Region() []byte { return b.region }
func (b *StuckBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), StuckTableType(), &b.Arena)
}
func (b *StuckBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), StuckTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *StuckBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), StuckTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *StuckBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

