// SpanReset restores Span's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func SpanReset(value *Span) {
	value.From = 0
	value.To = 0
}

func SpanMeasureBody(value *Span, ids *TableIds) int64 {
	bytes := int64(1)
	if value.From != 0 {
		bytes += tableLebBytes(ids.refAtHit(216, 0x7f845078d7a5c0b5)) + 1 + 8
	} // from
	if value.To != 0 {
		bytes += tableLebBytes(ids.refAtHit(18, 0x08c83907b56ac0a4)) + 1 + 8
	} // to
	if ids.Overflow {
		return -1
	}
	return bytes
}

func SpanMeasure(value *Span) int64 {
	var ids TableIds
	body := SpanMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func SpanMeasureReason(value *Span) (int64, error) {
	size := SpanMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
