func SuppressedLoadMessages(values []Suppressed, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !SuppressedLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// HeartbeatReset restores Heartbeat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func HeartbeatReset(value *Heartbeat) {
	value.At = 0
	value.Ticks = 0
	value.Error = 0
	value.Failures = 0
	value.TickOverrun = 0
	value.Due = 0
	clear(value.Revisions[:])
	value.Landed = 0
	value.All = 0
	value.Full = 0
	value.Looked = 0
	value.Fresh = TableList[LineRow]{}
	value.Quiet = TableList[LaneQuietRow]{}
	SuppressedReset(&value.Suppressed)
}

func HeartbeatMeasureBody(value *Heartbeat, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !HeartbeatSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func HeartbeatSaveBody(w *TableWriter, value *Heartbeat) bool {
	if !HeartbeatSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
