func HeartbeatLoadBuilder(b *HeartbeatBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, HeartbeatTableType(), HeartbeatTableType().NodeType, 2, report)
}

type HeartbeatBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *HeartbeatBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Heartbeat{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	HeartbeatReset((*Heartbeat)(p))
	return true
}
func (b *HeartbeatBuilder) GetRoot() *Heartbeat {
	if b.Arena.Locked {
		return nil
	}
	return (*Heartbeat)(b.Arena.At(b.root))
}
func (b *HeartbeatBuilder) AsConst() *Heartbeat {
	if len(b.region) == 0 {
		return nil
	}
	return (*Heartbeat)(unsafe.Pointer(&b.region[0]))
}
func (b *HeartbeatBuilder) Region() []byte { return b.region }
func (b *HeartbeatBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), HeartbeatTableType(), &b.Arena)
}
func (b *HeartbeatBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), HeartbeatTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *HeartbeatBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), HeartbeatTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *HeartbeatBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
