// PlaceExpectReset restores PlaceExpect's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func PlaceExpectReset(value *PlaceExpect) {
	value.Row = 0
	value.Col = 0
}

func PlaceExpectMeasureBody(value *PlaceExpect, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !PlaceExpectSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func PlaceExpectSaveBody(w *TableWriter, value *PlaceExpect) bool {
	if !PlaceExpectSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func PlaceExpectSaveBodyFields(w *TableWriter, value *PlaceExpect) bool {
	{
		if value.Row != 0 {
			if ref := w.Ids.refAtHit(240, 0x8a0bc1196111ad9b); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Row == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Row)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.Col != 0 {
			if ref := w.Ids.refAtHit(422, 0xf604f3190d016791); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Col == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Col)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func PlaceExpectLoadBody(r *TableReader, value *PlaceExpect) bool {
	PlaceExpectReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x8a0bc1196111ad9b: // row
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Row, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xf604f3190d016791: // col
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Col, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

