type BatchManifestBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *BatchManifestBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(BatchManifest{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	BatchManifestReset((*BatchManifest)(p))
	return true
}
func (b *BatchManifestBuilder) GetRoot() *BatchManifest {
	if b.Arena.Locked {
		return nil
	}
	return (*BatchManifest)(b.Arena.At(b.root))
}
func (b *BatchManifestBuilder) AsConst() *BatchManifest {
	if len(b.region) == 0 {
		return nil
	}
	return (*BatchManifest)(unsafe.Pointer(&b.region[0]))
}
func (b *BatchManifestBuilder) Region() []byte { return b.region }
func (b *BatchManifestBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), BatchManifestTableType(), &b.Arena)
}
func (b *BatchManifestBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), BatchManifestTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *BatchManifestBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), BatchManifestTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *BatchManifestBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
