// PropWriteReset restores PropWrite's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func PropWriteReset(value *PropWrite) {
	value.LogicalTable = 0
	value.Name = 0
	value.Value = 0
	value.Was = 0
	value.WasAbsent = false
}

func PropWriteMeasureBody(value *PropWrite, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !PropWriteSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func PropWriteSaveBody(w *TableWriter, value *PropWrite) bool {
	if !PropWriteSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
