func PropWriteLoadBuilder(b *PropWriteBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, PropWriteTableType(), PropWriteTableType().NodeType, 2, report)
}

type PropWriteBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *PropWriteBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(PropWrite{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	PropWriteReset((*PropWrite)(p))
	return true
}
func (b *PropWriteBuilder) GetRoot() *PropWrite {
	if b.Arena.Locked {
		return nil
	}
	return (*PropWrite)(b.Arena.At(b.root))
}
func (b *PropWriteBuilder) AsConst() *PropWrite {
	if len(b.region) == 0 {
		return nil
	}
	return (*PropWrite)(unsafe.Pointer(&b.region[0]))
}
func (b *PropWriteBuilder) Region() []byte { return b.region }
func (b *PropWriteBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), PropWriteTableType(), &b.Arena)
}
func (b *PropWriteBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), PropWriteTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *PropWriteBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), PropWriteTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *PropWriteBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// QueuedChangeReset restores QueuedChange's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func QueuedChangeReset(value *QueuedChange) {
	value.Entry = 0
	value.Prop = 0
	value.Verb = 0
	value.Actor = 0
	value.Moved = 0
}

func QueuedChangeMeasureBody(value *QueuedChange, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !QueuedChangeSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func QueuedChangeSaveBody(w *TableWriter, value *QueuedChange) bool {
	if !QueuedChangeSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
