type TimersBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *TimersBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Timers{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	TimersReset((*Timers)(p))
	return true
}
func (b *TimersBuilder) GetRoot() *Timers {
	if b.Arena.Locked {
		return nil
	}
	return (*Timers)(b.Arena.At(b.root))
}
func (b *TimersBuilder) AsConst() *Timers {
	if len(b.region) == 0 {
		return nil
	}
	return (*Timers)(unsafe.Pointer(&b.region[0]))
}
func (b *TimersBuilder) Region() []byte { return b.region }
func (b *TimersBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), TimersTableType(), &b.Arena)
}
func (b *TimersBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), TimersTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *TimersBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), TimersTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *TimersBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
func TimersOpenTimersAdd(worker *TableWorker, holder *TableList[TimerRow]) *TimerRow {
	p := (*TimerRow)(tableContainerAppend(worker, (*tableContainer)(unsafe.Pointer(holder)), int64(unsafe.Sizeof(*new(TimerRow)))))
	if p == nil {
		return nil
	}
	TimerReset(p)
	return p
}
func TimersOpenTimersErase(arena *TableArena, holder *TableList[TimerRow], element *TimerRow) bool {
	return tableContainerErase(arena, (*tableContainer)(unsafe.Pointer(holder)), unsafe.Pointer(element), int64(unsafe.Sizeof(*element)))
}
func TimersOpenTimersEach(holder *TableList[TimerRow], visit func(*TimerRow) bool, arena ...*TableArena) bool {
	cursor := tableContainerCursorBegin((*tableContainer)(unsafe.Pointer(holder)), int64(unsafe.Sizeof(*new(TimerRow))), tableOptionalArena(arena))
	for i := int32(0); i < holder.Count; i++ {
		p := (*TimerRow)(cursor.Next())
		if p == nil || !visit(p) {
			return false
		}
	}
	return true
}

